function getDice()
    local dice = {}
    local b = self.getBounds()
    local left  = b.center.x - b.size.x/2
    local right = b.center.x + b.size.x/2
    local back  = b.center.z - b.size.z/2
    local front = b.center.z + b.size.z/2
    local ybot  = b.center.y - b.size.y/2
    local ytop  = b.center.y + b.size.y/2 + 3

    if currentMat == "Red" then
        right = right - 5
        back  = back  + 2.9
        front = front - 0.5
    else
        left  = left  + 5
        back  = back  + 0.5
        front = front - 2.9
    end

    local lethalGUID = (currentMat == "Red")
        and Global.getVar("redLethalHits_GUID")
        or   Global.getVar("blueLethalHits_GUID")
    local lzone = getObjectFromGUID(lethalGUID)
    local lbound
    if lzone then
        local lb = lzone.getBounds()
        lbound = {
            minx = lb.center.x - lb.size.x/2,
            maxx = lb.center.x + lb.size.x/2,
            minz = lb.center.z - lb.size.z/2,
            maxz = lb.center.z + lb.size.z/2,
            miny = lb.center.y - lb.size.y/2,
            maxy = lb.center.y + lb.size.y/2
        }
    end

    for _, o in ipairs(getAllObjects()) do
        if o.tag == "Dice" and o.resting then
            local p = o.getPosition()
            if p.x > left and p.x < right
            and p.z > back and p.z < front
            and p.y > ybot and p.y < ytop
            and not (lbound
                and p.x > lbound.minx and p.x < lbound.maxx
                and p.z > lbound.minz and p.z < lbound.maxz
                and p.y > lbound.miny and p.y < lbound.maxy)
            then
                table.insert(dice, o)
            end
        end
    end

    return dice
end



