    end
end

function getPack9sBaseRadius(obj)
    if obj.hasTag and obj.hasTag("rectangularMeasuring") then
        local size = obj.getBoundsNormalized().size
        return math.sqrt((size.x / 2) * (size.x / 2) + (size.z / 2) * (size.z / 2))
    end

    local base = determineBaseInInches(obj)
    if base and base.x and base.z then
        return math.max(base.x, base.z)
    end

    local size = obj.getBoundsNormalized().size
    return math.max(size.x, size.z) / 2
end

function pack9sDistanceSq(a, b)
    local dx = a.x - b.x
    local dz = a.z - b.z
    return dx * dx + dz * dz
end

local pack9sCandidateCache = {}

function pack9sCandidatePoints(radius, step)
    local radialStep = step or 0.35
    -- The candidate grid only depends on (radius, step), both constant per pack
    -- size, so cache it and skip the regen+sort on every button press.
    local cacheKey = string.format("%.4f|%.4f", radius, radialStep)
    local cached = pack9sCandidateCache[cacheKey]
    if cached then return cached end

    local points = {{x = 0, z = 0, score = 0, r2 = 0}}
    local ring = radialStep

    while ring <= radius + 0.0001 do
        local circumference = 2 * math.pi * ring
        local count = math.max(8, math.ceil(circumference / radialStep))
        local r2 = ring * ring  -- precomputed radial distance² for fast bound checks
        for i = 0, count - 1 do
            local angle = (2 * math.pi * i) / count
            points[#points + 1] = {
                x = math.cos(angle) * ring,
                z = math.sin(angle) * ring,
                score = ring,
                r2 = r2,
            }
        end
        ring = ring + radialStep
    end

    table.sort(points, function(a, b)
        if a.score == b.score then
            if a.x == b.x then
                return a.z < b.z
            end
            return a.x < b.x
        end
        return a.score < b.score
    end)

    pack9sCandidateCache[cacheKey] = points
    return points
end

-- Hot path: maxCenterDistSq / maxPairDistanceSq are passed pre-squared and the
-- distance check is inlined to avoid per-candidate sqrt and function-call cost.
-- maxCenterDistSq already accounts for the model's base radius, so a passing
-- candidate keeps the whole base inside the 9" circle.
function pack9sCandidateFits(candidate, item, placed, maxCenterDistSq, spacing, maxPairDistanceSq)
    if candidate.r2 > maxCenterDistSq + 0.0001 then
        return false
    end

    local cx, cz = candidate.x, candidate.z
    local itemRadius = item.radius
    for _, other in ipairs(placed) do
        local minDist = itemRadius + other.radius + spacing
        local dx = cx - other.x
        local dz = cz - other.z
        local distSq = dx * dx + dz * dz
        if distSq < (minDist * minDist) - 0.0001 then
            return false
        end
        if distSq > maxPairDistanceSq + 0.0001 then
            return false
        end
    end

    return true
end

function pack9sPlacementIsValid(placed, spacing, maxPairDistance)
    for i = 1, #placed do
        for j = i + 1, #placed do
            local a = placed[i]
            local b = placed[j]
            local distSq = pack9sDistanceSq(a, b)
            local minDist = a.radius + b.radius + spacing
            if distSq < (minDist * minDist) - 0.0001 then
                return false
            end
            if distSq > (maxPairDistance * maxPairDistance) + 0.0001 then
                return false
            end
        end
    end
    return true
end

function pack9sTryBuildPlacement(items, center, spacing, candidates, packRadius, maxPairDistance)
    local placed = {}
    local maxPairDistanceSq = maxPairDistance * maxPairDistance
    local centerX, centerZ = center.x, center.z

    for _, item in ipairs(items) do
        -- Keep the whole base inside the circle: the model centre may sit at most
        -- (packRadius - baseRadius) from the centre so its far edge lands on the
        -- 9" ring rather than poking out past it.
        local maxCenterDist = packRadius - item.radius
        if maxCenterDist < 0 then
            return nil  -- base is wider than the 9" circle; cannot be wholly inside
        end
        local maxCenterDistSq = maxCenterDist * maxCenterDist

        local best = nil
        local bestScore = nil
        local itemPosX, itemPosZ = item.pos.x, item.pos.z
        for _, candidate in ipairs(candidates) do
            if pack9sCandidateFits(candidate, item, placed, maxCenterDistSq, spacing, maxPairDistanceSq) then
                local dx = (centerX + candidate.x) - itemPosX
                local dz = (centerZ + candidate.z) - itemPosZ
                local score = (dx * dx + dz * dz) + (candidate.score * 0.05)
                if best == nil or score < bestScore then
                    best = candidate
                    bestScore = score
                end
            end
        end

        if not best then
            return nil
        end

        placed[#placed + 1] = {item = item, x = best.x, z = best.z, radius = item.radius}
    end

    if not pack9sPlacementIsValid(placed, spacing, maxPairDistance) then
        return nil
    end

    return placed
end

function pack9sFindPlacement(items, center, candidates, packRadius, maxPairDistance)
    -- Feasibility is monotonic in spacing: loosening the gap only adds valid
    -- candidate positions, so if a layout fits at some gap it fits at any smaller
    -- gap. Binary-search the 0.25" grid (2.00 .. 0.00) for the largest feasible
    -- gap instead of trying every value top-down. Same result, ~4 builds not ~9.
    local step = 0.25
    local lo, hi = 0, 8  -- grid index i -> spacing = i * step  (8 -> 2.00")
    local bestPlaced, bestSpacing = nil, nil

    while lo <= hi do
        local mid = math.floor((lo + hi) / 2)
        local spacing = mid * step
        local placed = pack9sTryBuildPlacement(items, center, spacing, candidates, packRadius, maxPairDistance)
        if placed then
            bestPlaced, bestSpacing = placed, spacing
            lo = mid + 1   -- feasible: try for a larger gap
        else
            hi = mid - 1   -- too tight: shrink the gap
        end
    end

    return bestPlaced, bestSpacing
end

function arrangeSelectedModelsWithin9Circle(a, b, c)
    local playerColor = selectedPack9sPlayerColor(a, b)
    local playerObj = playerColor and Player[playerColor] or nil
    if not playerObj then
        pack9sMessage(playerColor, "player could not be resolved.")
        return
    end

    local objs = playerObj.getSelectedObjects()
    if not objs or #objs == 0 then
        pack9sMessage(playerColor, "select the models to pack first.")
        return
    end

    local maxPairDistance = 9
    local packRadius = maxPairDistance / 2
    local center = {x = 0, z = 0}
    local items = {}

    for _, obj in ipairs(objs) do
        local pos = obj.getPosition()
        center.x = center.x + pos.x
        center.z = center.z + pos.z
        local radius = getPack9sBaseRadius(obj)
        table.insert(items, {obj = obj, pos = pos, y = pos.y, radius = radius})
    end

    center.x = center.x / #items
    center.z = center.z / #items

    table.sort(items, function(a, b)
        return a.radius > b.radius
    end)

    -- A single base whose diameter exceeds 9" can never sit wholly inside the circle.
    if items[1].radius * 2 > maxPairDistance + 0.0001 then
        pack9sMessage(playerColor, "a selected base is " .. string.format("%.1f", items[1].radius * 2) .. "\" across, larger than the 9\" circle.")
        return
    end

    for i = 1, #items do
        for j = i + 1, #items do
            local requiredDistance = items[i].radius + items[j].radius
            if requiredDistance > maxPairDistance then
                pack9sMessage(playerColor, "two selected bases need " .. string.format("%.1f", requiredDistance) .. "\" between centres without overlapping, which is more than 9\".")
                return
            end
        end
    end

    local candidates = pack9sCandidatePoints(packRadius, 0.3)
    local placed, usedSpacing = pack9sFindPlacement(items, center, candidates, packRadius, maxPairDistance)
    if not placed then
        pack9sMessage(playerColor, "could not fit " .. #items .. " selected models inside a 9\" diameter without overlapping.")
        return
    end

    for _, placement in ipairs(placed) do
        local item = placement.item
        item.newPos = {x = center.x + placement.x, y = item.y, z = center.z + placement.z}
        item.obj.setPositionSmooth(item.newPos)
    end

    if usedSpacing >= 1.999 then
        printToColor("Packed " .. #items .. " models inside 9\" with a 2\" gap.", playerColor, "Green")
    else
        printToColor("Packed " .. #items .. " models inside 9\" with a reduced " .. string.format("%.2f", usedSpacing) .. "\" gap.", playerColor, "Yellow")
    end
end

function determineBaseInInches(model)
    local savedBase = model.getTable("chosenBase")

    if savedBase ~= nil then
        return savedBase.base
    else
        local chosenBase =  VALID_BASE_SIZES_IN_MM[1]
        local modelSize = model.getBoundsNormalized().size
        local modelSizeX = modelSize.x
        local modelSizeZ = modelSize.z
        local closestSum = 10000000000
        local chosenBaseIdx = 1

        for k, base in pairs(VALID_BASE_SIZES_IN_MM) do
            local baseInchX = (MM_TO_INCH - 0.001) * base.x
            local baseInchZ = (MM_TO_INCH - 0.001) * base.z
            if modelSizeX > baseInchX and modelSizeZ > baseInchZ then
                local distSum = (modelSizeX - baseInchX) + (modelSizeZ - baseInchZ)
                if distSum < closestSum then
                    closestSum = distSum
                    chosenBase = base
                    chosenBaseIdx = k
                end
            end
        end

        if chosenBase == nil then
            chosenBase = { x=modelSizeX/2, z=modelSizeZ/2}
        else
            chosenBase = {
                x = (chosenBase.x * MM_TO_INCH)/2,
                z = (chosenBase.z * MM_TO_INCH)/2
            }
        end

        model.setTable("chosenBase", { baseIdx=chosenBaseIdx, base=chosenBase })

        return chosenBase
    end
end

function getCircleVectorPoints(radius, baseX, baseZ, obj)
    local result = {}
    local scaleFactor = 1/obj.getScale().x
    local rotationDegrees =  obj.getRotation().y
    local steps = 64
    local degrees,sin,cos,toRads = 360/steps, math.sin, math.cos, math.rad

    for i = 0,steps do
        table.insert(result,{
            x = cos(toRads(degrees*i))*((radius+baseX)*scaleFactor),
            z = MEASURING_RING_Y_OFFSET,
            y = sin(toRads(degrees*i))*((radius+baseZ)*scaleFactor)
        })
    end

    return result
end

function getRectangleVectorPoints(radius, sizeX, sizeZ, obj)
    local result = {}
    local scaleFactor = 1/obj.getScale().x

    sizeX = sizeX*scaleFactor
    sizeZ = sizeZ*scaleFactor
    radius = radius*scaleFactor

    local steps = 65
    local degrees,sin,cos,toRads = 360/(steps-1), math.sin, math.cos, math.rad
    local xOffset,zOffset = sizeX,sizeZ
    table.insert(result,{
        x = (cos(toRads(degrees*0))*radius)+sizeX-0.001,
        y = (sin(toRads(degrees*0))*radius)+sizeZ,
        z = MEASURING_RING_Y_OFFSET
    })

    for i = 1,steps-1 do
        if i == 16 then
            table.insert(result,{ x= sizeX, y=(radius+sizeZ), z=MEASURING_RING_Y_OFFSET })
            table.insert(result,{ x=-sizeX, y=(radius+sizeZ), z=MEASURING_RING_Y_OFFSET })
            xOffset = -sizeX
        elseif i == 33 then
            table.insert(result,{ x=-radius-sizeX,       y= sizeZ, z=MEASURING_RING_Y_OFFSET })
            table.insert(result,{ x=-radius-sizeX-0.001, y=-sizeZ, z=MEASURING_RING_Y_OFFSET })
            table.insert(result,{ x=-radius-sizeX,       y=-sizeZ, z=MEASURING_RING_Y_OFFSET })
            zOffset = -sizeZ
        elseif i == 49 then
            table.insert(result,{ x=-sizeX, y=-radius-sizeZ, z=MEASURING_RING_Y_OFFSET })
            table.insert(result,{ x= sizeX, y=-radius-sizeZ, z=MEASURING_RING_Y_OFFSET })
            xOffset = sizeX
        elseif i == 65 then
            table.insert(result,{ x=radius+sizeX,       y=-sizeZ, z=MEASURING_RING_Y_OFFSET })
            table.insert(result,{ x=radius+sizeX-0.001, y= sizeZ, z=MEASURING_RING_Y_OFFSET })
        else
            table.insert(result,{
                x = (cos(toRads(degrees*i))*radius)+xOffset,
                y = (sin(toRads(degrees*i))*radius)+zOffset,
                z = MEASURING_RING_Y_OFFSET
            })
        end
    end
    table.insert(result,{
        x = (cos(toRads(degrees*0))*radius)+sizeX-0.001,
        y = (sin(toRads(degrees*0))*radius)+sizeZ,
        z = MEASURING_RING_Y_OFFSET
    })

    return result
end

