defaultTtsGameApiBaseUrl = "https://apistats.hutber.com/api/ttsGame"

function getTrackedSessionData()
    local ok, trackedSession = pcall(function()
        return Global.getTable("ttsTrackedSession")
    end)
    if ok and type(trackedSession) == "table" then
        return trackedSession
    end
    return nil
end

function getDiceRollApiBaseUrl()
    local trackedSession = getTrackedSessionData()
    if trackedSession and trackedSession.apiBaseUrl and trackedSession.apiBaseUrl ~= "" then
        return tostring(trackedSession.apiBaseUrl)
    end
    return defaultTtsGameApiBaseUrl
end

function getTrackedDiceGameId()
    local trackedSession = getTrackedSessionData()
    if not trackedSession then
        return nil
    end
    local gameId = tonumber(trackedSession.gameId)
    if gameId == nil then
        return nil
    end
    return math.floor(gameId)
end

function isTrackedDiceGameActive()
    local trackedSession = getTrackedSessionData()
    if not trackedSession then
        return false
    end
    return trackedSession.isGameActive == true
end

function getDicePlayerSide(color)
    if color == "Red" then
        return "red"
    elseif color == "Blue" then
        return "blue"
    end
    return nil
end

function getDiceTrackingColor(rollingColor)
    if rollingColor == "Red" or rollingColor == "Blue" then
        return rollingColor
    end
    if currentMat == "Red" or currentMat == "Blue" then
        return currentMat
    end
    return nil
end

function getTrackedPlayerIdentifierForDice(color)
    local playerRef = color and Player[color] or nil
    if playerRef and playerRef.steam_id and tostring(playerRef.steam_id) ~= "" then
        return tostring(playerRef.steam_id)
    end
    if playerRef and playerRef.steam_name and tostring(playerRef.steam_name) ~= "" then
        return tostring(playerRef.steam_name)
    end
    if color and color ~= "" then
        return string.lower(color) .. "_unknown"
    end
    return nil
end

function getTrackedConsentStatusForDice(color)
    local startMenuGuid = Global.getVar("startMenu_GUID")
    if not startMenuGuid then
        return nil
    end
    local startMenu = getObjectFromGUID(startMenuGuid)
    if not startMenu then
        return nil
    end
    local ok, state = pcall(function()
        return startMenu.call("getTrackedConsentPanelState", { side = color })
    end)
    if not ok or type(state) ~= "table" then
        return nil
    end
    return state.status
end

function diceRollUrlEncode(value)
    local text = tostring(value or "")
    text = text:gsub("\n", "\r\n")
    return text:gsub("([^%w%-_%.~])", function(char)
        return string.format("%%%02X", string.byte(char))
    end)
end

function appendDiceRollQuery(parts, key, value)
    if value == nil then
        return
    end
    local text = tostring(value)
    if text == "" then
        return
    end
    table.insert(parts, key .. "=" .. diceRollUrlEncode(text))
end

function buildDiceRollRequestUrl(payload)
    local parts = {}
    appendDiceRollQuery(parts, "game_id", payload.gameId)
    appendDiceRollQuery(parts, "steam_id", payload.steamId)
    appendDiceRollQuery(parts, "player_side", payload.playerSide)
    appendDiceRollQuery(parts, "rolled_at", payload.rolledAt)
    appendDiceRollQuery(parts, "results", payload.results and table.concat(payload.results, ",") or nil)
    return getDiceRollApiBaseUrl() .. "/diceRoll?" .. table.concat(parts, "&")
end

function submitResolvedRollBatch(results, rollingColor)
    if not WebRequest then
        return
    end
    if not isTrackedDiceGameActive() then
        return
    end

    local gameId = getTrackedDiceGameId()
    if gameId == nil then
        return
    end

    local trackingColor = getDiceTrackingColor(rollingColor)
    local playerSide = getDicePlayerSide(trackingColor)
    if playerSide == nil then
        return
    end

    local steamId = nil
    if getTrackedConsentStatusForDice(trackingColor) == "accepted" then
        steamId = getTrackedPlayerIdentifierForDice(trackingColor)
    end

    if type(results) ~= "table" or #results == 0 then
        return
    end

    for _, face in ipairs(results) do
        local value = tonumber(face)
        if value == nil or value < 1 or value > 6 or value ~= math.floor(value) then
            return
        end
    end

    local payload = {
        gameId = gameId,
        steamId = steamId,
        playerSide = playerSide,
        results = results,
        rolledAt = os.date("!%Y-%m-%dT%H:%M:%SZ")
    }

    local body = JSON.encode(payload)
    local url = buildDiceRollRequestUrl(payload)

    WebRequest.get(url, function(request)
        if request.is_error then
            return
        end

        local statusCode = tonumber(request.response_code) or 0
        if statusCode < 200 or statusCode >= 300 then
            return
        end
    end)
end

function importOpposDice(obj, player, alt)
    -- clear existing dice
    for _, d in ipairs(getDice()) do d.destroy() end

    -- get opposite mat and its bounds
    local oppMatGUID = (currentMat=="Red")
        and Global.getVar("blueCustomDiceMat_GUID")
        or   Global.getVar("redCustomDiceMat_GUID")
    local oppMat = getObjectFromGUID(oppMatGUID)
    if not oppMat then
        printToColor("Opposite dice mat not found.", player, "Orange")
        return
    end
    local mb = oppMat.getBounds()
    local mL, mR = mb.center.x - mb.size.x/2, mb.center.x + mb.size.x/2
    local mLo, mUp = mb.center.z - mb.size.z/2, mb.center.z + mb.size.z/2
    local mYl, mYh = mb.center.y - mb.size.y/2, mb.center.y + mb.size.y/2 + 3

    -- get opposite lethal zone and its bounds
    local oppLethalGUID = (currentMat=="Red")
        and Global.getVar("blueLethalHits_GUID")
        or   Global.getVar("redLethalHits_GUID")
    local oppLethal = getObjectFromGUID(oppLethalGUID)
    local lb, lL, lR, lLo, lUp, lYl, lYh
    if oppLethal then
        lb = oppLethal.getBounds()
        lL, lR = lb.center.x - lb.size.x/2, lb.center.x + lb.size.x/2
        lLo, lUp = lb.center.z - lb.size.z/2, lb.center.z + lb.size.z/2
        lYl, lYh = lb.center.y - lb.size.y/2, lb.center.y + lb.size.y/2 + 3
    else
        printToColor("Warning: opposite lethal zone not found.", player)
    end

    local toImport = {}
    local seen = {}

    -- gather dice: check lethal zone first, then main mat
    for _, o in ipairs(getAllObjects()) do
        if o.tag=="Dice" and o.resting then
            local p = o.getPosition()
            -- lethal zone?
            if lb
            and p.x > lL and p.x < lR
            and p.z > lLo and p.z < lUp
            and p.y > lYl and p.y < lYh
            then
                seen[o.getGUID()] = true
                table.insert(toImport, { die=o, origin=lb.center, lethal=true })
            -- main mat (excluding any already seen in lethal)
            elseif p.x > mL and p.x < mR
            and p.z > mLo and p.z < mUp
            and p.y > mYl and p.y < mYh
            and not seen[o.getGUID()]
            then
                seen[o.getGUID()] = true
                table.insert(toImport, { die=o, origin=mb.center, lethal=false })
            end
        end
    end

    if #toImport == 0 then
        printToColor("No dice found on the opposite mat.", player, "Yellow")
        return
    end

    -- clone into this mat: shift lethal dice by (-3, -3) in X/Z
    local mc = self.getBounds().center
    local count = 0
    for _, entry in ipairs(toImport) do
        local dp = entry.die.getPosition()
        local cb = entry.origin
        local relX, relY, relZ = -(dp.x - cb.x), dp.y - cb.y, -(dp.z - cb.z)
        local nx, ny, nz = mc.x + relX, mc.y + relY, mc.z + relZ
        if entry.lethal then
            local dx = (currentMat == "Red") and -6 or 6
            local dz = (currentMat == "Red") and 4.2 or -4.2
            nx = nx + dx
            nz = nz + dz
        end
        entry.die.clone({ position={nx, ny, nz}, snap_to_grid=false })
        count = count + 1
    end

    printToAll("Imported "..count.." dice from the opposite mat, including lethal hits.", {1,1,1})
end



local lastSpawnPosition = nil -- Keep track of the last spawned dice position
local diceCount = 0 -- Track the number of dice spawned in the current sequence
function storeCurrentDiceAsPreviousRoll()
    -- Build a snapshot of the current dice on the mat (positions, values, tints)
    local snapshot = {}
    for _, die in ipairs(getDice()) do
        local c = die.getCustomObject()
        local d = {
            pos  = die.getPosition(),
            rot  = die.getRotation(),
            val  = die.getValue(),
            tint = die.getColorTint(),
            customImage = nil
        }
        if c then d.customImage = c.image end
        table.insert(snapshot, d)
    end

    -- If we've undone some rolls and then store a new roll, drop any future redo history
    if previousRollIndex < #previousRollStack then
        for i = #previousRollStack, previousRollIndex + 1, -1 do
            table.remove(previousRollStack, i)
        end
    end

    table.insert(previousRollStack, snapshot)
    -- Trim stack to maximum size
    while #previousRollStack > maxPreviousRolls do
        table.remove(previousRollStack, 1)
    end
    previousRollIndex = #previousRollStack
    previousRollData = previousRollStack[previousRollIndex] or {}
end

function revertRoll(obj, player, alt)
    -- Undo one step in the previousRollStack. Use previousRollIndex to track position.
    if previousRollIndex == 0 or not previousRollStack or #previousRollStack == 0 then
        printToColor("No previous roll found.", player, "Red")
        return
    end

    local snapshot = previousRollStack[previousRollIndex]
    if not snapshot or #snapshot == 0 then
        printToColor("No previous roll data available.", player, "Red")
        return
    end

    -- Destroy current dice and spawn snapshot dice
    for _, die in ipairs(getDice()) do die.destroy() end
    for _, data in ipairs(snapshot) do
        local diceTypeToSpawn = "Die_6_Rounded"
        if data.customImage then
            diceTypeToSpawn = "Custom_Dice"
        elseif pipColorBtn.color == "Black" then
            diceTypeToSpawn = "Die_6"
        end
        local spawned = spawnObject({ type = diceTypeToSpawn, position = data.pos, rotation = data.rot })
        if data.customImage then spawned.setCustomObject({ image = data.customImage, type = 1 }) end
        spawned.setColorTint(data.tint)
        spawned.setValue(data.val)
    end

    printToColor("Reverted to roll #" .. tostring(previousRollIndex) .. " of " .. tostring(#previousRollStack), player, "Green")
    -- Move pointer back so another click reverts another step
    previousRollIndex = math.max(0, previousRollIndex - 1)
    previousRollData = previousRollStack[previousRollIndex] or {}
end

function redoRoll(obj, player, alt)
    -- Move forward in the previousRollStack if possible
    if not previousRollStack or #previousRollStack == 0 then
        printToColor("No roll history available.", player, "Red")
        return
    end
    if previousRollIndex >= #previousRollStack then
        printToColor("No newer roll to redo.", player, "Red")
        return
    end
    previousRollIndex = previousRollIndex + 1
    local snapshot = previousRollStack[previousRollIndex]
    if not snapshot or #snapshot == 0 then
        printToColor("No roll data at this index.", player, "Red")
        return
    end
    for _, die in ipairs(getDice()) do die.destroy() end
    for _, data in ipairs(snapshot) do
        local diceTypeToSpawn = "Die_6_Rounded"
        if data.customImage then
            diceTypeToSpawn = "Custom_Dice"
        elseif pipColorBtn.color == "Black" then
            diceTypeToSpawn = "Die_6"
        end
        local spawned = spawnObject({ type = diceTypeToSpawn, position = data.pos, rotation = data.rot })
        if data.customImage then spawned.setCustomObject({ image = data.customImage, type = 1 }) end
        spawned.setColorTint(data.tint)
        spawned.setValue(data.val)
    end
    printToColor("Redone to roll #" .. tostring(previousRollIndex) .. " of " .. tostring(#previousRollStack), player, "Green")
    previousRollData = previousRollStack[previousRollIndex] or {}
end
function moveDiceToRoller(color, dice)
    roller.call("setPlayerColor", { color = color })
    for _, die in ipairs(dice) do
        roller.call("setLastHolder", { obj = die, color = color })
        roller.putObject(die)
    end

    -- Add this line at the end:
    storeCurrentDiceAsPreviousRoll()
    -- Infer roll phase and calculate stats
    inferRollPhase(dice)
end

-- Evaluate a simple arithmetic expression safely (digits, + - * / and parentheses)
-- Returns number on success, or nil + error message on failure
local function evalSimpleExpr(expr)
  if type(expr) ~= "string" then return nil, "invalid input" end
  local s = expr:gsub("[xX]", "*")
  s = s:gsub("%s+", "")
  if s == "" then return nil, "empty" end
  -- allow only digits, operators and parentheses
  if s:find("[^%d%+%-%*/%(%)]") then return nil, "invalid characters" end

  -- tokenize
  local tokens = {}
  local i, n = 1, #s
  while i <= n do
    local c = s:sub(i, i)
    if c:match("%d") then
      local j = i
      while j <= n and s:sub(j, j):match("%d") do j = j + 1 end
      table.insert(tokens, tonumber(s:sub(i, j - 1)))
      i = j
    elseif c == '-' then
      -- handle unary minus by inserting 0 before '-'
      local prev = tokens[#tokens]
      local prevIsOp = (prev == nil) or (prev == '+') or (prev == '-') or (prev == '*') or (prev == '/') or (prev == '(')
      if prevIsOp then table.insert(tokens, 0) end
      table.insert(tokens, '-')
      i = i + 1
    elseif c == '+' or c == '*' or c == '/' or c == '(' or c == ')' then
      table.insert(tokens, c)
      i = i + 1
    else
      return nil, "invalid token"
    end
  end

  -- shunting-yard to RPN
  local output, ops = {}, {}
  local prec = { ['+'] = 1, ['-'] = 1, ['*'] = 2, ['/'] = 2 }
  local function isop(x) return prec[x] ~= nil end
  for _, t in ipairs(tokens) do
    if type(t) == 'number' then
      table.insert(output, t)
    elseif t == '(' then
      table.insert(ops, t)
    elseif t == ')' then
      local found = false
      while #ops > 0 do
        local top = ops[#ops]
        table.remove(ops)
        if top == '(' then found = true break end
        table.insert(output, top)
      end
      if not found then return nil, "mismatched parentheses" end
    elseif isop(t) then
      while #ops > 0 and isop(ops[#ops]) and prec[ops[#ops]] >= prec[t] do
        table.insert(output, ops[#ops])
        table.remove(ops)
      end
      table.insert(ops, t)
    else
      return nil, "invalid token"
    end
  end
  while #ops > 0 do
    local top = ops[#ops]
    table.remove(ops)
    if top == '(' then return nil, "mismatched parentheses" end
    table.insert(output, top)
  end

  -- evaluate RPN
  local stack = {}
  local function pop2()
    local b = stack[#stack]; stack[#stack] = nil
    local a = stack[#stack]; stack[#stack] = nil
    if a == nil or b == nil then return nil end
    return a, b
  end
  for _, t in ipairs(output) do
    if type(t) == 'number' then
      table.insert(stack, t)
    else
      local a, b = pop2()
      if a == nil then return nil, "invalid expression" end
      if t == '+' then table.insert(stack, a + b)
      elseif t == '-' then table.insert(stack, a - b)
      elseif t == '*' then table.insert(stack, a * b)
      elseif t == '/' then
        if b == 0 then return nil, "division by zero" end
        table.insert(stack, a / b)
      else
        return nil, "invalid operator"
      end
    end
  end
  if #stack ~= 1 then return nil, "invalid expression" end
  return stack[1]
end

function setCustomDiceCount(_, player, value, _)
  -- Accept either a plain number or a simple math expression
  local num = tonumber(value)
  if not num then
    local result, err = evalSimpleExpr(tostring(value or ""))
    if result then num = result end
  end
  if num and num > 0 and num <= 128 then
    customDiceCount = math.floor(num)
  else
    printToColor("Invalid Number! Enter a number or expression between 1 and 128.", player, "Red")
  end
end

function spawnCustomDice(_, player, _)
    if customDiceCount and customDiceCount > 0 then
        spawnDice(customDiceCount, player)
        customDiceCount = nil -- Reset custom dice count
        self.editInput({index = 0, value = ""}) -- Clear the input field (replace index if needed)
        printToColor("Custom Dice Count reset after spawning.", player, "Yellow")
    else
        printToColor("No valid custom dice count set.", player, "Red")
    end
end

function autoRoll(obj, player, alt, numDice)
    numDice = numDice or 1
    local total = 0
    local rolledResults = {}
    local directionMultiplier = (currentMat == "Blue") and 1 or -1
    local startX = self.getPosition().x + (currentMat == "Blue" and -16 or 16)
    local startY = self.getPosition().y + 1
    local startZ = self.getPosition().z
    if lastSpawnPosition then
        startX = lastSpawnPosition.x
        startY = lastSpawnPosition.y
        startZ = lastSpawnPosition.z
    end
    local diceColors = {
        {0.627, 0.124, 0.941}, -- purple
        {1, 0.341, 0.2},       -- orange
        {0.203, 0.674, 0.325}, -- green
        {0.160, 0.596, 0.965}, -- blue
        {0.898, 0.223, 0.509}, -- pink
        {0.254, 0.211, 0.098}, -- brown
        {1, 0.298, 0.298},     -- red
        {0.345, 0.184, 0.506}, -- indigo
        {0.988, 0.761, 0.498}, -- light orange
        {0.847, 0.647, 0.125}, -- gold
    }

    local colorIndex = math.random(#diceColors)
    local rollColor = diceColors[colorIndex]
    for i = 1, numDice do
        local result = math.random(6)
        total = total + result
        table.insert(rolledResults, result)
        printToAll(player .. " rolled a D6: " .. result, stringColorToRGB(player))
        local position = {
            x = startX + directionMultiplier * (i - 1) * 1.5,
            y = startY,
            z = startZ
        }
        local die = spawnObject({
            type = "Die_6_Rounded",
            position = position,
            rotation = {0, 180, 0}
        })
        if die then
            die.setValue(result)
            die.setColorTint(rollColor)
            die.setCustomObject({
                type = 1,
                image = customDiceImage,
                face = 1,
                font_color = {0, 0, 0}
            })
            diceCount = diceCount + 1
            lastSpawnPosition = {
                x = position.x + directionMultiplier * 1.5,
                y = position.y,
                z = position.z
            }
            if diceCount >= 5 then
                lastSpawnPosition = nil
                diceCount = 0
            end
        else
            printToColor("Failed to spawn a die for roll " .. i, player, "Red")
        end
    end
    printToAll(player .. " rolled a total of " .. total .. " (" .. numDice .. "D6)", stringColorToRGB(player))
    submitResolvedRollBatch(rolledResults, player)
end



