function sustainedHitsAction(_, color, alt)
    -- Left-click: apply 6+. Right-click (alt): apply 5+. No toggle.
    local threshold = alt and 5 or 6
    local diceToClone = {}

    -- Helper: compare positions (x,z) with small epsilon
    local function near_pos(a, b, eps)
        eps = eps or 0.5
        if not a or not b then return false end
        local dx = a.x - b.x
        local dz = a.z - b.z
        return (dx*dx + dz*dz) <= (eps*eps)
    end

    -- Helper: compare color tint approximately
    local function near_tint(a, b, eps)
        eps = eps or 0.05
        if not a or not b then return false end
        return math.abs(a[1]-b[1]) <= eps and math.abs(a[2]-b[2]) <= eps and math.abs(a[3]-b[3]) <= eps
    end

    -- Match previous roll entries to current dice by value + tint + approximate position
    if previousRollData and #previousRollData > 0 then
        local prevCandidates = {}
        for _, d in ipairs(previousRollData) do
            if d.val >= threshold then
                table.insert(prevCandidates, d)
            end
        end

        if #prevCandidates > 0 then
            local currentDice = getDice()
            local used = {}
            for _, prev in ipairs(prevCandidates) do
                for i, die in ipairs(currentDice) do
                    if not used[i] and die.getValue() == prev.val then
                        local tint_ok = near_tint(die.getColorTint(), prev.tint)
                        local pos_ok = near_pos(die.getPosition(), prev.pos)
                        if tint_ok and pos_ok then
                            table.insert(diceToClone, die)
                            used[i] = true
                            break
                        end
                    end
                end
            end
        end
    end

    -- Fallback: if we didn't collect any by roll-matching, fall back to global behavior
    if #diceToClone == 0 then
        for _, die in ipairs(getDice()) do
            if die.getValue() >= threshold then
                table.insert(diceToClone, die)
            end
        end
        printToAll("Warning: No previous roll match found — duplicated all current dice >= " .. threshold .. "+", {1,0.5,0.2})
    end

    local directionMultiplier = (currentMat == "Blue") and 1 or -1
    local count = 0
    for index, die in ipairs(diceToClone) do
        local p = die.getPosition()
        p.x = p.x + (8.5 * directionMultiplier)
        die.clone({position = p, snap_to_grid = false})
        count = count + 1
    end

    -- Log for all players
    printToAll("Sustained Hits duplicated: " .. tostring(count) .. " (threshold " .. tostring(threshold) .. "+)")
end


-- New function for combined action
function sustainedLethalHitsAction(_, color, alt)
    -- Left-click: apply 6+. Right-click: apply 5+. No toggle.
    local threshold = alt and 5 or 6
    local sixPositions = {}
    local sixDice = {}

    local function near_pos(a, b, eps)
        eps = eps or 0.5
        if not a or not b then return false end
        local dx = a.x - b.x
        local dz = a.z - b.z
        return (dx*dx + dz*dz) <= (eps*eps)
    end
    local function near_tint(a, b, eps)
        eps = eps or 0.05
        if not a or not b then return false end
        return math.abs(a[1]-b[1]) <= eps and math.abs(a[2]-b[2]) <= eps and math.abs(a[3]-b[3]) <= eps
    end

    if previousRollData and #previousRollData > 0 then
        local prevCandidates = {}
        for _, d in ipairs(previousRollData) do
            if d.val >= threshold then
                table.insert(prevCandidates, d)
            end
        end
        if #prevCandidates > 0 then
            local currentDice = getDice()
            local used = {}
            for _, prev in ipairs(prevCandidates) do
                for i, die in ipairs(currentDice) do
                    if not used[i] and die.getValue() == prev.val then
                        local tint_ok = near_tint(die.getColorTint(), prev.tint)
                        local pos_ok = near_pos(die.getPosition(), prev.pos)
                        if tint_ok and pos_ok then
                            table.insert(sixDice, die)
                            table.insert(sixPositions, die.getPosition())
                            used[i] = true
                            break
                        end
                    end
                end
            end
        end
    end

    -- Fallback to global selection if none matched
    if #sixDice == 0 then
        for _, die in ipairs(getDice()) do
            if die.getValue() >= threshold then
                table.insert(sixDice, die)
                table.insert(sixPositions, die.getPosition())
            end
        end
        printToAll("Warning: No previous roll match found — duplicated all current dice >= " .. threshold .. "+", {1,0.5,0.2})
    end

    -- Move lethal hits using same left/right semantics
    lethalHitsAction('sustainedAndLethal', color, alt)

    local directionMultiplier = (currentMat == "Blue") and 1 or -1
    local count = 0
    for i, die in ipairs(sixDice) do
        local p = sixPositions[i]
        p.x = p.x + (8.5 * directionMultiplier)
        die.clone({position = p, snap_to_grid = false})
        count = count + 1
    end
    printToAll("Sustained & Lethal duplicated: " .. tostring(count) .. " (threshold " .. tostring(threshold) .. "+)")
end

